      value
    }

    /// Get a `i8` value from the buffer, return an error if the buffer does not have enough bytes.
    #[inline]
    pub fn get_i8(&mut self) -> Result<i8, IncompleteBuffer> {
      self.get_u8().map(|v| v as i8)
