  pub(crate) fn flush_async(&self) -> std::io::Result<()> {
    match &self.backend {
      #[cfg(all(feature = "memmap", not(target_family = "wasm")))]
      MemoryBackend::MmapMut { buf: mmap, .. } => unsafe { (**mmap).flush_async() },
      _ => Ok(()),
    }
  }

  #[cfg(all(feature = "memmap", not(target_family = "wasm")))]
  pub(crate) fn flush_range(&self, offset: usize, len: usize) -> std::io::Result<()> {
    match &self.backend {
      #[cfg(all(feature = "memmap", not(target_family = "wasm")))]
      MemoryBackend::MmapMut { buf: mmap, .. } => unsafe {
        let mmap = &**mmap;
        let mmap_len = mmap.len();
        if offset + len > mmap_len {
          return Err(range_out_of_bounds(offset, len, mmap_len));
        }

        mmap.flush_range(offset, len)
      },
      _ => Ok(()),
    }
  }

  #[cfg(all(feature = "memmap", not(target_family = "wasm")))]
  pub(crate) fn flush_async_range(&self, offset: usize, len: usize) -> std::io::Result<()> {
    match &self.backend {
      #[cfg(all(feature = "memmap", not(target_family = "wasm")))]
      MemoryBackend::MmapMut { buf: mmap, .. } => unsafe {
        let mmap = &**mmap;
        let mmap_len = mmap.len();
        if offset + len > mmap_len {
          return Err(range_out_of_bounds(offset, len, mmap_len));
        }

        mmap.flush_async_range(offset, len)
      },
      _ => Ok(()),
    }
  }

  #[cfg(all(feature = "memmap", not(target_family = "wasm")))]
  #[cfg_attr(docsrs, doc(cfg(all(feature = "memmap", not(target_family = "wasm")))))]
  pub(crate) fn flush_header_and_range(&self, offset: usize, len: usize) -> std::io::Result<()> {
    match &self.backend {
      #[cfg(all(feature = "memmap", not(target_family = "wasm")))]
      MemoryBackend::MmapMut { buf: mmap, .. } => unsafe {
        let mmap = &**mmap;
        let mmap_len = mmap.len();
        if len == 0 {
          return mmap.flush_range(self.header_offset, mem::size_of::<H>());
        }

        if offset + len > mmap_len {
          return Err(range_out_of_bounds(offset, len, mmap_len));
        }

        let header_offset = self.header_offset;
        let header_size = mem::size_of::<H>();
        let page_size = (*PAGE_SIZE) as usize;

        let header_range_start = header_offset;
        let header_range_end = header_offset + header_size;
        let header_start_page = header_range_start / page_size;
        let header_end_page = header_range_end.div_ceil(page_size);

        let flush_end = offset + len;
        let range_start_page = offset / page_size;
        let range_end_page = flush_end.div_ceil(page_size);

        if header_start_page == range_start_page && header_end_page == range_end_page {
          let start = header_offset.min(offset);
          return mmap.flush_range(start, header_range_end.max(flush_end) - start);
        }

        if offset <= header_offset && header_range_end <= flush_end {
          return mmap.flush_range(offset, len);
        }

        mmap
          .flush_range(header_offset, header_size)
          .and_then(|_| mmap.flush_range(offset, len))
      },
      _ => Ok(()),
    }
  }

  #[cfg(all(feature = "memmap", not(target_family = "wasm")))]
  #[cfg_attr(docsrs, doc(cfg(all(feature = "memmap", not(target_family = "wasm")))))]
  pub(crate) fn flush_async_header_and_range(
    &self,
    offset: usize,
    len: usize,
  ) -> std::io::Result<()> {
    match &self.backend {
      #[cfg(all(feature = "memmap", not(target_family = "wasm")))]
      MemoryBackend::MmapMut { buf: mmap, .. } => unsafe {
        let mmap = &**mmap;
        let mmap_len = mmap.len();
        if len == 0 {
          return mmap.flush_async_range(self.header_offset, mem::size_of::<H>());
        }

        if offset + len > mmap_len {
          return Err(range_out_of_bounds(offset, len, mmap_len));
        }

        let header_offset = self.header_offset;
        let header_size = mem::size_of::<H>();
        let page_size = (*PAGE_SIZE) as usize;

        let header_range_start = header_offset;
        let header_range_end = header_offset + header_size;
        let header_start_page = header_range_start / page_size;
        let header_end_page = header_range_end.div_ceil(page_size);

        let flush_end = offset + len;
        let range_start_page = offset / page_size;
        let range_end_page = flush_end.div_ceil(page_size);

        if header_start_page == range_start_page && header_end_page == range_end_page {
          let start = header_offset.min(offset);
          return mmap.flush_async_range(start, header_range_end.max(flush_end) - start);
        }

        if offset <= header_offset && header_range_end <= flush_end {
          return mmap.flush_async_range(offset, len);
        }

        mmap
          .flush_async_range(header_offset, header_size)
          .and_then(|_| mmap.flush_async_range(offset, len))
      },
      _ => Ok(()),
    }
  }

  #[allow(dead_code)]
  #[inline]
  pub(crate) const fn as_ptr(&self) -> *const u8 {
    self.ptr
  }

  #[inline]
  pub(crate) const fn as_mut_ptr(&self) -> *mut u8 {
    self.ptr
  }

  #[inline]
  pub(crate) fn header(&self) -> &H {
    unsafe {
      match &self.header_ptr {
        Either::Left(header_ptr_offset) => &*self.ptr.add(*header_ptr_offset as usize).cast::<H>(),
        Either::Right(header) => header,
      }
    }
  }

  #[inline]
  pub(crate) fn header_mut(&mut self) -> &mut H {
    unsafe {
      match &mut self.header_ptr {
        Either::Left(header_ptr_offset) => {
          &mut *self.ptr.add(*header_ptr_offset as usize).cast::<H>()
        }
        Either::Right(header) => header,
      }
    }
  }

  #[inline]
  pub(crate) const fn cap(&self) -> u32 {
    self.cap
  }

  #[inline]
  pub(crate) const fn refs(&self) -> &R {
    &self.refs
  }

  /// Only works on mmap with a file backend, unmounts the memory mapped file and truncates it to the specified size.
  ///
  /// ## Safety:
  /// - This method must be invoked in the drop impl of `Arena`.
  pub(crate) unsafe fn unmount(&mut self) {
    unsafe {
      #[cfg(all(feature = "memmap", not(target_family = "wasm")))]
      if self.lock_meta {
        let _ = self.munlock(self.header_offset, mem::size_of::<H>());
      }

      // Any errors during unmapping/closing are ignored as the only way
      // to report them would be through panicking which is highly discouraged
      // in Drop impls, c.f. https://github.com/rust-lang/lang-team/issues/97

      #[cfg(all(feature = "memmap", not(target_family = "wasm")))]
      match &mut self.backend {
        MemoryBackend::MmapMut {
          buf,
          file,
          path,
          remove_on_drop,
          ..
        } => {
          if remove_on_drop.load(Ordering::Acquire) {
            let _ = Box::from_raw(*buf);
            core::ptr::drop_in_place(file);
            let _ = std::fs::remove_file(path.as_path());
            return;
          }

          let _ = Box::from_raw(*buf);
          let _ = file.sync_all();
        }
        MemoryBackend::Mmap {
          path,
          file,
          buf,
          remove_on_drop,
          ..
        } => {
          if remove_on_drop.load(Ordering::Acquire) {
            let _ = Box::from_raw(*buf);
            core::ptr::drop_in_place(file);
            let _ = std::fs::remove_file(path.as_path());
            return;
          }

          let _ = Box::from_raw(*buf);
        }
        _ => {}
      }
    }
  }
}

#[inline]
fn header_meta<H>(reserved: usize, unify: bool) -> (usize, usize) {
  if unify {
    let offset = align_offset::<H>(reserved as u32) as usize + mem::align_of::<H>();
    (offset, offset + mem::size_of::<H>())
  } else {
    (reserved + 1, reserved + 1)
  }
}

#[inline]
fn check_capacity<H>(reserved: usize, unify: bool, capacity: usize) -> Result<usize, Error> {
  let (header_ptr_offset, prefix_size) = header_meta::<H>(reserved, unify);

  if prefix_size > capacity {
    return Err(Error::InsufficientSpace {
      requested: prefix_size as u32,
      available: capacity as u32,
    });
  }

  Ok(header_ptr_offset)
}

use core::{
  mem::MaybeUninit,
  ptr::{self, NonNull},
};

use super::*;

#[derive(Debug)]
enum Kind<T> {
  Slot(MaybeUninit<T>),
  Inline(NonNull<T>),
  /// zero-sized type
  Dangling(NonNull<T>),
}

impl<T> Default for Kind<T> {
  fn default() -> Self {
    if mem::size_of::<T>() == 0 {
      Kind::Dangling(NonNull::dangling())
    } else if mem::needs_drop::<T>() {
      Kind::Slot(MaybeUninit::uninit())
    } else {
      Kind::Inline(NonNull::dangling())
    }
  }
}

/// An owned to a value `T` in the ARENA.
#[derive(Debug)]
#[must_use = "The `T` is uninitialized, and must be initialized by `write` before it is used, if `T` is not zero sized type."]
pub struct Owned<T, A: Allocator> {
  kind: Kind<T>,
  arena: A,
  detached: bool,
  pub(super) allocated: Meta,
}

unsafe impl<A: Allocator + Send, T> Send for Owned<T, A> {}
unsafe impl<A: Allocator + Sync, T> Sync for Owned<T, A> {}

impl<T, A: Allocator> crate::Buffer for Owned<T, A> {
  /// Returns how many bytes of `T` occupies.
  ///
  /// If this value is `0`, then the `T` is ZST (zero sized type).
  #[inline]
  fn capacity(&self) -> usize {
    self.allocated.ptr_size as usize
  }

  /// Returns the offset of `T` to the pointer of the ARENA.
  ///
  /// If this value is `0`, then the `T` is ZST (zero sized type).
  #[inline]
  fn offset(&self) -> usize {
    self.allocated.ptr_offset as usize
  }

  /// Returns how many bytes of buffer the value occupies.
  ///
  /// If this value is `0`, then the `T` is ZST (zero sized type).
  #[inline]
  fn buffer_capacity(&self) -> usize {
    self.allocated.memory_size as usize
  }

  /// Returns the offset to the pointer of the ARENA.
  ///
  /// If this value is `0`, then the `T` is ZST (zero sized type).
  #[inline]
  fn buffer_offset(&self) -> usize {
    self.allocated.memory_offset as usize
  }

  #[inline]
  unsafe fn detach(&mut self) {
    self.detached = true;
  }

  #[cfg(all(feature = "memmap", not(target_family = "wasm")))]
  fn flush(&self) -> std::io::Result<()> {
    self.arena.flush_range(
      self.allocated.ptr_offset as usize,
      self.allocated.ptr_size as usize,
    )
  }

  /// Asynchronously flush the buffer to the disk.
  #[cfg(all(feature = "memmap", not(target_family = "wasm")))]
  fn flush_async(&self) -> std::io::Result<()> {
    self.arena.flush_async_range(
      self.allocated.memory_offset as usize,
      self.allocated.memory_size as usize,
    )
  }
}

impl<T, A: Allocator> Owned<T, A> {
  /// Write a value to the `RefMut`.
  #[inline]
  pub fn write(&mut self, value: T) {
    match &mut self.kind {
      Kind::Slot(slot) => unsafe {
        slot.as_mut_ptr().write(value);
      },
      Kind::Inline(ptr) => unsafe {
        ptr.as_ptr().write(value);
      },
      Kind::Dangling(_) => {}
    }
  }

  /// Returns a shared reference to the value.
  ///
  /// ## Safety
  /// - The value must be initialized.
  pub unsafe fn as_ref(&self) -> &T {
    unsafe {
      match &self.kind {
        Kind::Slot(slot) => slot.as_ptr().as_ref().unwrap(),
        Kind::Inline(ptr) => ptr.as_ref(),
        Kind::Dangling(val) => val.as_ref(),
      }
    }
  }

  /// Returns a mutable reference to the value.
  ///
  /// ## Safety
  /// - The value must be initialized.
  pub unsafe fn as_mut(&mut self) -> &mut T {
    unsafe {
      match &mut self.kind {
        Kind::Slot(slot) => slot.as_mut_ptr().as_mut().unwrap(),
        Kind::Inline(ptr) => ptr.as_mut(),
        Kind::Dangling(val) => val.as_mut(),
      }
    }
  }

  /// Returns the pointer to the `T`, the pointer may not be initialized.
  /// If the pointer is not initialized, then [`NonNull::dangling()`] is returned.
  pub fn as_mut_ptr(&mut self) -> NonNull<T> {
    match &mut self.kind {
      // SAFETY: MaybeUninit always has a valid, non-null pointer to its storage.
      Kind::Slot(slot) => unsafe { NonNull::new_unchecked(slot.as_mut_ptr()) },
      Kind::Inline(ptr) => *ptr,
      Kind::Dangling(val) => *val,
    }
  }
}

impl<T, A: Allocator> Drop for Owned<T, A> {
  fn drop(&mut self) {
    match &mut self.kind {
      Kind::Slot(slot) => {
        if !self.detached {
          unsafe {
            if mem::needs_drop::<T>() {
              let ptr = slot.as_mut_ptr();
              if !ptr.is_null() {
                ptr::drop_in_place(ptr);
              }
            }
          }
          // SAFETY: offset and offset + size are inbounds of the ARENA.
          unsafe {
            self
              .arena
              .dealloc(self.allocated.memory_offset, self.allocated.memory_size);
          }
        }
      }
      Kind::Inline(_) => {
        if !self.detached {
          // SAFETY: offset and offset + size are inbounds of the ARENA.
          unsafe {
            self
              .arena
              .dealloc(self.allocated.memory_offset, self.allocated.memory_size);
          }
        }
      }
      Kind::Dangling(_) => {}
    }
  }
}

/// A mutable reference to a value `T` in the ARENA.
#[derive(Debug)]
#[must_use = "The `T` is uninitialized, and must be initialized by `write` before it is used, if `T` is not zero sized type."]
pub struct RefMut<'a, T, A: Allocator> {
  kind: Kind<T>,
  arena: &'a A,
  detached: bool,
  pub(super) allocated: Meta,
}

impl<T, A: Allocator> crate::Buffer for RefMut<'_, T, A> {
  #[inline]
  fn capacity(&self) -> usize {
    self.allocated.ptr_size as usize
  }

  #[inline]
  fn offset(&self) -> usize {
    self.allocated.ptr_offset as usize
  }

  #[inline]
  fn buffer_capacity(&self) -> usize {
    self.allocated.memory_size as usize
  }

  #[inline]
  fn buffer_offset(&self) -> usize {
    self.allocated.memory_offset as usize
  }

  /// Detach the value from the ARENA, which means when the value is dropped,
  /// the underlying memory will not be collected for futhur allocation.
  ///
  /// ## Safety
  /// - If `T` is not inlined ([`core::mem::needs_drop::<T>()`](core::mem::needs_drop) returns `true`), then users should take care of dropping the value by themselves.
  #[inline]
  unsafe fn detach(&mut self) {
    self.detached = true;
  }

  #[cfg(all(feature = "memmap", not(target_family = "wasm")))]
  fn flush(&self) -> std::io::Result<()> {
    self.arena.flush_range(
      self.allocated.ptr_offset as usize,
      self.allocated.ptr_size as usize,
    )
  }

  #[cfg(all(feature = "memmap", not(target_family = "wasm")))]
  fn flush_async(&self) -> std::io::Result<()> {
    self.arena.flush_async_range(
      self.allocated.ptr_offset as usize,
      self.allocated.ptr_size as usize,
    )
  }
}

impl<'a, T, A: Allocator> RefMut<'a, T, A> {
  /// Write a value to the `RefMut`.
  #[inline]
  pub fn write(&mut self, value: T) {
    match &mut self.kind {
      Kind::Slot(slot) => unsafe {
        slot.as_mut_ptr().write(value);
      },
      Kind::Inline(ptr) => unsafe {
        ptr.as_ptr().write(value);
      },
      Kind::Dangling(_) => {}
    }
  }

  /// Returns a shared reference to the value.
  ///
  /// ## Safety
  /// - The value must be initialized.
  pub unsafe fn as_ref(&self) -> &T {
    unsafe {
      match &self.kind {
        Kind::Slot(slot) => slot.as_ptr().as_ref().unwrap(),
        Kind::Inline(ptr) => ptr.as_ref(),
        Kind::Dangling(val) => val.as_ref(),
      }
    }
  }

  /// Returns a mutable reference to the value.
  ///
  /// ## Safety
  /// - The value must be initialized.
  pub unsafe fn as_mut(&mut self) -> &mut T {
    unsafe {
      match &mut self.kind {
        Kind::Slot(slot) => slot.as_mut_ptr().as_mut().unwrap(),
        Kind::Inline(ptr) => ptr.as_mut(),
        Kind::Dangling(val) => val.as_mut(),
      }
    }
  }

  /// Returns the pointer to the `T`, the pointer may not be initialized.
  /// If the pointer is not initialized, then [`NonNull::dangling()`] is returned.
  pub fn as_mut_ptr(&mut self) -> NonNull<T> {
    match &mut self.kind {
      // SAFETY: MaybeUninit always has a valid, non-null pointer to its storage.
      Kind::Slot(slot) => unsafe { NonNull::new_unchecked(slot.as_mut_ptr()) },
      Kind::Inline(ptr) => *ptr,
      Kind::Dangling(val) => *val,
    }
  }

  #[inline]
  pub(super) fn new(slot: MaybeUninit<T>, allocated: Meta, arena: &'a A) -> Self {
    Self {
      kind: Kind::Slot(slot),
      arena,
      detached: false,
      allocated,
    }
  }

  #[inline]
  pub(super) fn new_inline(value: NonNull<T>, allocated: Meta, arena: &'a A) -> Self {
    Self {
      kind: Kind::Inline(value),
      arena,
      detached: false,
      allocated,
    }
  }

  #[inline]
  pub(super) fn new_zst(arena: &'a A) -> Self {
    Self {
      kind: Kind::Dangling(NonNull::dangling()),
      allocated: Meta::null(arena.raw_ptr() as _),
      arena,
      detached: false,
    }
  }

  #[allow(clippy::wrong_self_convention)]
  #[inline]
  pub(super) fn to_owned(&mut self) -> Owned<T, A> {
    self.detached = true;

    Owned {
      arena: self.arena.clone(),
      kind: mem::take(&mut self.kind),
      detached: false,
      allocated: self.allocated,
    }
  }
}

impl<T, A: Allocator> Drop for RefMut<'_, T, A> {
  fn drop(&mut self) {
    match &mut self.kind {
      Kind::Slot(slot) => {
        if !self.detached {
          unsafe {
            if mem::needs_drop::<T>() {
              let ptr = slot.as_mut_ptr();
              if !ptr.is_null() {
                ptr::drop_in_place(ptr);
              }
            }
          }
          // SAFETY: offset and offset + size are inbounds of the ARENA.
          unsafe {
            self
              .arena
              .dealloc(self.allocated.memory_offset, self.allocated.memory_size);
          }
        }
      }
      Kind::Inline(_) => {
        if !self.detached {
          // SAFETY: offset and offset + size are inbounds of the ARENA.
          unsafe {
            self
              .arena
              .dealloc(self.allocated.memory_offset, self.allocated.memory_size);
          }
        }
      }
      Kind::Dangling(_) => {}
    }
  }
}

use memmap2::MmapOptions;
use std::{
  fs::{File, OpenOptions},
  io,
  path::Path,
};

use super::{Allocator, Options};

impl Options {
  /// Set if lock the meta of the [`Allocator`](crate::Allocator) in the memory to prevent OS from swapping out the header of [`Allocator`](crate::Allocator).
  /// When using memory map backed [`Allocator`](crate::Allocator), the meta of the [`Allocator`](crate::Allocator)
  /// is in the header, meta is frequently accessed,
  /// lock (`mlock` on the header) the meta can reduce the page fault,
  /// but yes, this means that one [`Allocator`](crate::Allocator) will have one page are locked in memory,
  /// and will not be swapped out. So, this is a trade-off between performance and memory usage.
  ///
  /// Default is `true`.
  ///
  /// This configuration has no effect on windows and vec backed [`Allocator`](crate::Allocator).
  ///
  /// ## Example
  ///
  /// ```rust
  /// use rarena_allocator::Options;
  ///
  /// let opts = Options::new().with_lock_meta(false);
  /// ```
  #[inline]
  pub const fn with_lock_meta(mut self, lock_meta: bool) -> Self {
    self.lock_meta = lock_meta;
    self
  }

  /// Sets the option for read access.
  ///
  /// This option, when true, will indicate that the file should be
  /// `read`-able if opened.
  ///
  /// ## Examples
  ///
  /// ```rust
  /// use rarena_allocator::Options;
  ///
  /// let opts = Options::new().with_read(true);
  /// ```
  #[inline]
  #[cfg(all(feature = "memmap", not(target_family = "wasm")))]
  #[cfg_attr(docsrs, doc(cfg(all(feature = "memmap", not(target_family = "wasm")))))]
  pub const fn with_read(mut self, read: bool) -> Self {
    self.read = read;
    self
  }

  /// Sets the option for write access.
  ///
  /// This option, when true, will indicate that the file should be
  /// `write`-able if opened.
  ///
  /// If the file already exists, any write calls on it will overwrite its
  /// contents, without truncating it.
  ///
  /// ## Examples
  ///
  /// ```rust
  /// use rarena_allocator::Options;
  ///
  /// let opts = Options::new().with_write(true);
  /// ```
  #[inline]
  #[cfg(all(feature = "memmap", not(target_family = "wasm")))]
  #[cfg_attr(docsrs, doc(cfg(all(feature = "memmap", not(target_family = "wasm")))))]
  pub const fn with_write(mut self, write: bool) -> Self {
    self.write = write;
    self
  }

  /// Sets the option for the append mode.
  ///
  /// This option, when true, means that writes will append to a file instead
  /// of overwriting previous contents.
  /// Note that setting `.write(true).append(true)` has the same effect as
  /// setting only `.append(true)`.
  ///
  /// For most filesystems, the operating system guarantees that all writes are
  /// atomic: no writes get mangled because another process writes at the same
  /// time.
  ///
  /// One maybe obvious note when using append-mode: make sure that all data
  /// that belongs together is written to the file in one operation. This
  /// can be done by concatenating strings before passing them to [`write()`],
  /// or using a buffered writer (with a buffer of adequate size),
  /// and calling [`flush()`] when the message is complete.
  ///
  /// If a file is opened with both read and append access, beware that after
  /// opening, and after every write, the position for reading may be set at the
  /// end of the file. So, before writing, save the current position (using
  /// <code>[seek]\([SeekFrom](std::io::SeekFrom)::[Current]\(opts))</code>), and restore it before the next read.
  ///
  /// ## Note
  ///
  /// This function doesn't create the file if it doesn't exist. Use the
  /// [`Options::with_create`] method to do so.
  ///
  /// [`write()`]: std::io::Write::write "io::Write::write"
  /// [`flush()`]: std::io::Write::flush "io::Write::flush"
  /// [seek]: std::io::Seek::seek "io::Seek::seek"
  /// [Current]: std::io::SeekFrom::Current "io::SeekFrom::Current"
  ///
  /// ## Examples
  ///
  /// ```rust
  /// use rarena_allocator::Options;
  ///
  /// let opts = Options::new().with_append(true);
  /// ```
  #[inline]
