        let mut buf = arena.alloc_bytes((arena.page_size() * 2) as u32).unwrap();
        buf.set_len(arena.page_size() * 2);
        rand::rng().fill(&mut *buf);

        let cks = Crc32::new();
        let checksum = arena.checksum(&cks);

        assert_eq!(
