pub(crate) fn small_capacity_vec<A: Allocator + Debug>(unify: bool) {
  if !unify {
    let e = Options::new()
      .with_capacity(0)
      .with_unify(unify)
      .alloc::<A>()
      .unwrap_err();
    assert!(matches!(e, Error::InsufficientSpace { available: 0, .. }));

    assert!(
      Options::new()
        .with_capacity(1)
        .with_unify(unify)
        .alloc::<A>()
        .is_ok()
    );

    let e = Options::new()
      .with_capacity(40)
      .with_unify(unify)
      .with_reserved(40)
      .alloc::<A>()
      .unwrap_err();
    assert!(matches!(e, Error::InsufficientSpace { available: 40, .. }));
  } else {
    let e = Options::new()
      .with_capacity(1)
      .with_unify(true)
      .alloc::<A>()
      .unwrap_err();
    assert!(matches!(e, Error::InsufficientSpace { available: 1, .. }));

    let e = Options::new()
      .with_capacity(40)
      .with_reserved(40)
      .with_unify(true)
      .alloc::<A>()
      .unwrap_err();
    assert!(matches!(e, Error::InsufficientSpace { available: 40, .. }));
  }
}

